def solve(s: str) -> bool:
    # IPv4 address must consist of exactly four decimal numbers 0-255 separated by dots.
    # No leading/trailing spaces or other characters are allowed.
    # Leading zeros are not allowed unless the number is exactly '0'.
    # Use a strict regex to reject malformed strings early.
    if not isinstance(s, str):
        return False
    # quick pattern: four groups of digits separated by dots, no extra characters
    if not re.fullmatch(r"\d+(?:\.\d+){3}", s):
        return False
    parts = s.split('.')
    for p in parts:
        # leading zero check
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

