def solve(word1, word2):
    """Return the edit distance (Levenshtein) between *word1* and *word2*.
    Uses classic DP O(m*n) where m,n are lengths of the strings.
    """
    m, n = len(word1), len(word2)
    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    # Fill DP
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],     # deletion
                                   dp[i][j - 1],     # insertion
                                   dp[i - 1][j - 1]) # substitution
    return dp[m][n]

